def main():
    rnd = random.Random(2026)
    out = []
    for band, topic, d, q, opts, a, x in Q:
        assert 0 <= a < len(opts), q
        fixed = any("above" in o.lower() or o.lower().startswith("both") for o in opts)
        if not fixed:
            idx = list(range(len(opts)))
            rnd.shuffle(idx)
            opts2 = [opts[i] for i in idx]
            a = idx.index(a)
            opts = opts2
        out.append({"band": band, "topic": topic, "difficulty": {"E": "EASY", "M": "MEDIUM", "H": "HARD"}[d],
                    "text": q, "options": opts, "correctIndex": a, "explanation": x})
    path = os.path.join(os.path.dirname(__file__), "..", "backend", "src", "main", "resources", "seed", "questions.json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(out, f, indent=1, ensure_ascii=False)
    from collections import Counter
    print("total", len(out))
    print("by band", Counter(o["band"] for o in out))
    print("by answer", Counter(o["correctIndex"] for o in out))
    print("by difficulty", Counter((o["band"], o["difficulty"]) for o in out))
    print("topics", Counter(o["topic"] for o in out))

if __name__ == "__main__":
    main()
